<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><meta name="robots" content="noindex,nofollow,noarchive"><title>Security & Access - C-Net Library</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fa;margin:0;color:#172033}.wrap{max-width:1240px;margin:28px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.brand{font-size:12px;text-transform:uppercase;letter-spacing:1.3px;color:#0f766e;font-weight:800}.btn{display:inline-flex;align-items:center;justify-content:center;background:#102a43;color:#fff;border:1px solid #102a43;border-radius:9px;padding:9px 12px;cursor:pointer;text-decoration:none;font-weight:700}.btn.alt{background:#fff;color:#102a43;border-color:#ccd7e1}.muted{color:#718096}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:18px}.stat,.card{background:#fff;border:1px solid #e1e8ef;border-radius:15px;padding:17px;box-shadow:0 6px 22px rgba(15,23,42,.035)}.stat strong{display:block;font-size:25px;color:#102a43}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{margin-bottom:16px}.permGroups{display:grid;gap:13px;margin:14px 0}.permGroup{background:#f8fafc;border-radius:11px;padding:11px}.permGroup strong{display:block;margin-bottom:7px;color:#334e68}.perm{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.users{display:grid;gap:10px}.row{border:1px solid #e2e8f0;border-radius:12px;padding:13px}.field{margin:10px 0}input[type=text],input[type=search],select{width:100%;padding:9px;border:1px solid #ccd7e1;border-radius:9px;background:#fff}.filter{display:grid;grid-template-columns:2fr 1fr auto;gap:8px;margin-bottom:13px}.tableWrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:720px}.table th,.table td{padding:10px;border-bottom:1px solid #edf0f4;text-align:left;font-size:13px}.table th{font-size:11px;text-transform:uppercase;color:#64748b}.badge{display:inline-block;background:#e8f5f2;color:#0f766e;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:800}.roleList{display:flex;gap:5px;flex-wrap:wrap;margin:7px 0}.dangerNote{font-size:12px;color:#9a3412;background:#fff7ed;padding:8px;border-radius:8px;margin-bottom:10px}@media(max-width:1000px){.stats{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:620px){.wrap{padding:0 13px}.top{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:1fr 1fr}.perm{grid-template-columns:1fr}.filter{grid-template-columns:1fr}.filter .btn{width:100%}}</style></head><body><div class="wrap"><div class="top"><div><div class="brand">Administration</div><h1 style="margin:2px 0">Security, Roles & Audit</h1><div class="muted">Control backoffice access, branch scope and review administrative activity.</div></div><a class="btn alt" href="{{ route('admin.dashboard') }}">Dashboard</a></div>@if(session('success'))<div class="card" style="background:#f0fdf4;border-color:#86efac">{{ session('success') }}</div>@endif @if($errors->any())<div class="card" style="background:#fef2f2;border-color:#fca5a5"><ul style="margin:0;padding-left:18px">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif
<div class="stats"><div class="stat"><span class="muted">Users</span><strong>{{ $securityStats['users'] }}</strong></div><div class="stat"><span class="muted">Backoffice</span><strong>{{ $securityStats['backoffice_users'] }}</strong></div><div class="stat"><span class="muted">Global Admins</span><strong>{{ $securityStats['global_users'] }}</strong></div><div class="stat"><span class="muted">Roles</span><strong>{{ $securityStats['roles'] }}</strong></div><div class="stat"><span class="muted">Permissions</span><strong>{{ $securityStats['permissions'] }}</strong></div><div class="stat"><span class="muted">Audit Events</span><strong>{{ $securityStats['audit_events'] }}</strong></div></div>
<div class="grid"><div><h2>Role Permission Matrix</h2><div class="dangerNote">Permission changes affect every user assigned to that role. Review selections carefully before saving.</div>@foreach($roles as $role)<div class="card"><h3 style="margin-top:0">{{ $role->name }}</h3><div class="muted">{{ $role->permissions->count() }} permissions currently assigned</div><form method="POST" action="{{ route('admin.security.roles.update',$role) }}">@csrf @method('PATCH')<div class="permGroups">@foreach($permissions->groupBy('group') as $group=>$groupPermissions)<div class="permGroup"><strong>{{ ucfirst(str_replace(['-','_'],' ',$group ?: 'general')) }}</strong><div class="perm">@foreach($groupPermissions as $permission)<label><input type="checkbox" name="permissions[]" value="{{ $permission->id }}" @checked($role->permissions->contains('id',$permission->id))> {{ $permission->name }}</label>@endforeach</div></div>@endforeach</div><button class="btn" type="submit">Save {{ $role->name }} Permissions</button></form></div>@endforeach</div>
<div><h2>User Access</h2><form class="filter" method="GET"><input type="search" name="user_search" value="{{ request('user_search') }}" placeholder="Search user or email"><select name="branch_id"><option value="">All branches</option>@foreach($branches as $branch)<option value="{{ $branch->id }}" @selected((string)request('branch_id')===(string)$branch->id)>{{ $branch->name }}</option>@endforeach</select><button class="btn" type="submit">Filter</button></form><div class="users">@forelse($users as $user)<form class="row" method="POST" action="{{ route('admin.security.users.roles.update',$user) }}">@csrf @method('PATCH')<strong>{{ $user->name }}</strong><div class="muted">{{ $user->email }} · Account type: {{ $user->role ?: '—' }}</div><div class="roleList">@forelse($user->roles as $assignedRole)<span class="badge">{{ $assignedRole->name }}</span>@empty<span class="muted">No RBAC role assigned</span>@endforelse</div><div class="field"><label>Operating Branch<select name="branch_id"><option value="">Global / None</option>@foreach($branches as $branch)<option value="{{ $branch->id }}" @selected((string)$user->branch_id===(string)$branch->id)>{{ $branch->name }}</option>@endforeach</select></label></div><div class="field">@foreach($roles as $role)<label style="display:block;margin:5px 0"><input type="checkbox" name="roles[]" value="{{ $role->id }}" @checked($user->roles->contains('id',$role->id))> {{ $role->name }}</label>@endforeach</div><button class="btn" type="submit">Update Access</button></form>@empty<div class="card muted">No users match the current filter.</div>@endforelse</div></div></div>
<div class="card"><div class="top" style="margin-bottom:12px"><div><h2 style="margin:0">Recent Audit Trail</h2><div class="muted">Latest 100 matching administrative events.</div></div><form method="GET" style="display:flex;gap:7px"><input type="search" name="audit_search" value="{{ request('audit_search') }}" placeholder="Action, user, entity or IP"><button class="btn" type="submit">Search</button></form></div><div class="tableWrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>IP Address</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at?->format('d M Y H:i') }}</td><td>{{ $log->user?->name ?? 'System' }}@if($log->user?->email)<div class="muted">{{ $log->user->email }}</div>@endif</td><td><span class="badge">{{ $log->action }}</span></td><td>{{ $log->auditable_type ? class_basename($log->auditable_type).' #'.$log->auditable_id : '—' }}</td><td>{{ $log->ip_address ?: '—' }}</td></tr>@empty<tr><td colspan="5" class="muted">No matching audit activity.</td></tr>@endforelse</tbody></table></div></div></div></body></html>